raw.css:
:root{--color-brand-dark:#0f5c5b;--color-brand-darker:#0a403f;--color-accent-on-dark:#8fe3e1;--color-bg:#ffffff;--color-bg-alt:#f2f7f7;--color-bg-card:#ffffff;--color-text:#1a2b2b;--color-text-muted:#3f5555;--color-border:#d9e6e5;--font-base:Georgia,'Times New Roman',serif;--font-ui:Verdana,Arial,sans-serif;--space-xs:0.5rem;--space-sm:1rem;--space-md:1.5rem;--space-lg:2.5rem;--space-xl:4rem;--radius:0.5rem;--max-width:75rem;}
*,*::before,*::after{box-sizing:border-box;}
html{font-size:100%;}
body{margin:0;font-family:var(--font-ui);color:var(--color-text);background-color:var(--color-bg);line-height:1.6;}
h1,h2,h3{font-family:var(--font-base);line-height:1.25;color:var(--color-brand-darker);margin-top:0;}
p{margin-top:0;margin-bottom:var(--space-sm);}
a{color:var(--color-brand-dark);text-decoration:underline;}
a:hover{color:var(--color-brand-darker);}
a:focus-visible,button:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:3px solid var(--color-brand-dark);outline-offset:2px;}
.container{max-width:var(--max-width);margin:0 auto;padding:0 1.25rem;width:100%;}

header{background-color:var(--color-bg);border-bottom:1px solid var(--color-border);}
.header-inner{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:var(--space-sm);padding-top:var(--space-sm);padding-bottom:var(--space-sm);}
.logo{font-family:Georgia,'Times New Roman',serif;text-transform:uppercase;font-size:clamp(1.1rem,3vw,1.3rem);letter-spacing:0.2em;color:var(--color-brand-dark);text-decoration:none;border-top:3px double var(--color-brand-dark);border-bottom:3px double var(--color-brand-dark);padding:0.3rem 0.6rem;display:inline-block;}
.logo:hover{color:var(--color-brand-darker);}
nav ul.nav-list{list-style:none;display:flex;flex-wrap:wrap;gap:var(--space-sm);margin:0;padding:0;}
nav ul.nav-list a{text-decoration:none;color:var(--color-text);font-weight:bold;padding:0.5rem 0.25rem;}
nav ul.nav-list a:hover,nav ul.nav-list a:focus-visible{color:var(--color-brand-dark);}

main{display:block;}
section{padding:var(--space-xl) 0;}
section.alt-bg{background-color:var(--color-bg-alt);}
section.dark-bg{background-color:var(--color-brand-dark);color:#ffffff;}
section.dark-bg h1,section.dark-bg h2,section.dark-bg h3{color:var(--color-accent-on-dark);}
section.dark-bg a{color:var(--color-accent-on-dark);}

.grid{display:grid;gap:var(--space-md);grid-template-columns:1fr;}

.card{background-color:var(--color-bg-card);border:1px solid var(--color-border);border-radius:var(--radius);padding:var(--space-md);}
.card h3{margin-bottom:var(--space-xs);}
.card img{max-width:100%;height:auto;border-radius:var(--radius);display:block;}

.btn{display:inline-block;min-height:44px;padding:0.75rem 1.5rem;background-color:var(--color-brand-dark);color:#ffffff;border:none;border-radius:var(--radius);font-weight:bold;text-decoration:none;cursor:pointer;font-size:1rem;}
.btn:hover{background-color:var(--color-brand-darker);}
.btn:focus-visible{outline:3px solid var(--color-accent-on-dark);outline-offset:2px;}

form{display:flex;flex-direction:column;gap:var(--space-sm);max-width:40rem;}
.form-row{display:flex;flex-direction:column;gap:0.3rem;}
label{font-weight:bold;}
input,select,textarea{min-height:44px;padding:0.6rem;border:1px solid var(--color-border);border-radius:var(--radius);font-family:inherit;font-size:1rem;background-color:#ffffff;color:var(--color-text);}
textarea{min-height:8rem;resize:vertical;}
input:focus-visible,textarea:focus-visible,select:focus-visible{outline:3px solid var(--color-brand-dark);outline-offset:1px;}

footer{background-color:var(--color-brand-darker);color:#ffffff;padding:var(--space-lg) 0;}
footer p{color:#ffffff;margin:0.2rem 0;}
.footer-name{font-weight:bold;font-size:1.1rem;}
.footer-copy{margin-top:var(--space-sm);font-size:0.9rem;color:var(--color-accent-on-dark);}

@media (prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important;}}

@media (max-width:600px){.header-inner{flex-direction:column;align-items:flex-start;}nav ul.nav-list{flex-direction:column;gap:0.25rem;width:100%;}section{padding:var(--space-lg) 0;}.grid{grid-template-columns:1fr;}form{max-width:100%;}}

@media (min-width:601px){.grid-2{grid-template-columns:repeat(2,1fr);}.grid-3{grid-template-columns:repeat(3,1fr);}nav ul.nav-list{justify-content:flex-end;}}

